/* @lc app=leetcode id=3316 lang=kotlin */ class Solution { fun maxRemovals(source: String, pattern: String, targetIndices: IntArray): Int = targetIndices.toHashSet().let { ts -> source.indices.fold(IntArray(pattern.length + 1) { if (it == 0) 0 else -1_000_000 }) { dp, i -> IntArray(pattern.length + 1) { j -> maxOf(dp[j] + (if (i in ts) 1 else 0), if (j > 0 && source[i] == pattern[j - 1]) dp[j - 1] else -1_000_000) } }.last() } }